-- Slevohlídka — rozšíření katalogu a kategorie Domov a zábava (R174)
--
-- 32 nových produktů podle akcí, které žádný produkt nechytal (25. 10. 2026, 3 679 z 13 839
-- aktuálních akcí): Kinder, adventní kalendář, čokoládové figurky a kolekce, lentilky a dražé,
-- polevy a zdobení, listové těsto, sušené ovoce, semínka, kompoty, kukuřice a hrášek, špenát
-- a mražená zelenina, obalované polotovary, sýr na gril, romadur a tvarůžky, polotvrdý sýr,
-- ovocné pálenky, kachna a husa, tlačenka, uzená pečeně, sádlo, lahůdkové saláty, čerstvé
-- bylinky, květák, celer, lesní plody, exotické ovoce, rostlinný jogurt, podmáslí, řepkový
-- olej, hummus, kokosové mléko, úklidové rukavice. Nová pravidla 28 produktů (značky piv
-- a lihovin, rozpustná káva, Activia, Veselá kráva, třtinový cukr, antitranspirant, tvary
-- těstovin, parfém na prádlo, Tatranky, pralinky…) a kategorie 12 produktů nepotravinového
-- zboží z oddělení „Domov a zábava“ (Elektro, Dílna, Auto, Památka zesnulým, Domácí potřeby).
--
-- Skript je OPAKOVATELNÝ a nezávisí na pořadí s cronem kategorií: kategorie, na které
-- produkty odkazují, založí i s nadřazenými (INSERT IGNORE podle jedinečného `source_id`,
-- existující nezmění — zbytek oddělení „Domov a zábava“ doplní cron `import-categories`).
-- Produkty se hledají podle jedinečného názvu (`products.name`), existující dostanou pravidla
-- a kategorii z tohoto skriptu (ruční úpravy těchto 72 produktů v /katalog přepíše).
-- Přiřazení akcí (offer_product) dopočítá aplikace při dalším stažení akcí každého obchodu
-- (cron); uložení produktu v /katalog ho přepočítá hned.
--
-- Vygenerováno z vývojové databáze po CatalogSeeder.
--
-- @author Roman Hlaváček
-- @created 2026-10-25

SET NAMES utf8mb4;

-- Kategorie, na které produkty odkazují (s nadřazenými) — chybějící se založí, existující nezmění

-- Produkty: 32 nových, 40 s novými pravidly nebo kategorií
ON DUPLICATE KEY UPDATE
    `keywords` = VALUES(`keywords`),
    `variant_keywords` = VALUES(`variant_keywords`),
    `exclude_keywords` = VALUES(`exclude_keywords`),
    `category_id` = VALUES(`category_id`),
    `updated_at` = NOW();
